template <typename Iter>
class reverse_iterator {
    Iter current; // Underlying base iterator
public:
    using difference_type = typename Iter::difference_type;

    // RI + N operation (forward movement in reverse sequence)
    reverse_iterator operator+(difference_type n) const
    {
        // Compiler maps +N steps in reverse to:
        // -N steps on the base iterator.
        return reverse_iterator(current - n);
    }
};

// Requires underlying iterator (Iter) to support operator- (Random Access)
// Memory Implications: No extra storage required, only offset translation.
